\choice
{ ${\dfrac{5}{14}}cm$   }
   {  ${\dfrac{95}{21}}cm$  }
     { \True ${\dfrac{95}{14}}cm$  }
    { ${\dfrac{95}{7}}cm$   }
\loigiai{
\begin{tikzpicture}
    % Vẽ đường tròn tâm O bán kính 3
    \coordinate (O) at (0, 0);
    \draw[thick] (O) circle(3);

    % Đặt các điểm A, E sao cho AE là đường kính
    \coordinate (A) at (-3, 0);
    \coordinate (E) at (3, 0);

    % Đặt điểm B sao cho tam giác ABE vuông tại B
    \coordinate (B) at (0, 3);

    % Tính tọa độ điểm C trên đoạn AB
    \coordinate (C) at ($(A)!0.6!(B)$); % Điểm C nằm trên đoạn AB, cách A 60% đoạn AB

    % Tính tọa độ điểm D, với CD vuông góc với OA tại D
    \coordinate (D) at ($(O)!(C)!(A)$); % D là hình chiếu vuông góc của C lên OA

    % Vẽ tam giác ABE
    \draw[thick] (A) -- (B) -- (E) -- cycle;

    % Vẽ đoạn CD
    \draw[thick] (C) -- (D);
        \path
    (B) pic[draw=black,fill=white, angle radius = 5] {right angle = A--B--E};

    % Vẽ dấu vuông tại D để chỉ rõ CD vuông góc với OA
    \draw (D) rectangle +(0.3,0.3);

    % Vẽ đường kính AE
    \draw[dashed] (A) -- (E);

    % Vẽ các điểm A, B, C, D, E, O
    \fill (O) circle(1.5pt) node[above left] {$O$};
    \fill (A) circle(1.5pt) node[left] {$A$};
    \fill (B) circle(1.5pt) node[above] {$B$};
    \fill (E) circle(1.5pt) node[right] {$E$};
    \fill (C) circle(1.5pt) node[above left] {$C$};
    \fill (D) circle(1.5pt) node[below right] {$D$};

    % Vẽ góc vuông tại B

    \end{tikzpicture}
Vẽ đường kính ${AE}$ có $AE=28cm$\\
Điểm ${B}$ thuộc đường kính ${AE}$ nên suy ra $\widehat{ABE}=90^{\circ}$\\
Xét $ \Delta{ABC}$ và $\Delta{ADE}$ có $\widehat{A}$ chung, $\widehat{ABE}=\widehat{ADC}=90^{\circ}$\\
Do đó $\Delta ADC\,\sim\Delta ABE$ (g.g)\\
Suy ra $\dfrac{AD}{AB} = \dfrac {AC}{AE}$ suy ra $AD= \dfrac{AC.AB}{AE} =\dfrac{10.19} {28}=\dfrac{95}{14}cm$
}\end{ex}

